    public bool GetTouchpadFinger(int touchpad, int finger, out bool down, out float x, out float y, out float pressure) => Sdl.GetGamepadTouchpadFinger(this, touchpad, finger, out down, out x, out y, out pressure);

    /// <summary>Return whether a gamepad has a particular sensor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GamepadHasSensor</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_GetGamepadSensorData</c>, <c>SDL_GetGamepadSensorDataRate</c>,
    /// <c>SDL_SetGamepadSensorEnabled</c>.
    /// </para>
    /// </remarks>
    /// <param name="type">the type of sensor to query.</param>
    /// <returns>true if the sensor exists, false otherwise.</returns>
    public bool HasSensor(SensorType type) => Sdl.GamepadHasSensor(this, type);

    /// <summary>Set whether data reporting for a gamepad sensor is enabled.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetGamepadSensorEnabled</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GamepadHasSensor</c>, <c>SDL_GamepadSensorEnabled</c>.</para>
    /// </remarks>
    /// <param name="type">the type of sensor to enable/disable.</param>
    /// <param name="enabled">whether data reporting should be enabled.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool SetSensorEnabled(SensorType type, bool enabled) => Sdl.SetGamepadSensorEnabled(this, type, enabled);

    /// <summary>Query whether sensor data reporting is enabled for a gamepad.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GamepadSensorEnabled</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_SetGamepadSensorEnabled</c>.</para>
    /// </remarks>
    /// <param name="type">the type of sensor to query.</param>
    /// <returns>true if the sensor is enabled, false otherwise.</returns>
    public bool SensorEnabled(SensorType type) => Sdl.GamepadSensorEnabled(this, type);

    /// <summary>Get the data rate (number of events per second) of a gamepad sensor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadSensorDataRate</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="type">the type of sensor to query.</param>
    /// <returns>the data rate, or 0.0f if the data rate is not available.</returns>
    public float GetSensorDataRate(SensorType type) => Sdl.GetGamepadSensorDataRate(this, type);

    /// <summary>Get the current state of a gamepad sensor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadSensorData</c>.</para>
    /// <para>
    /// The number of values and interpretation of the data is sensor dependent. See the remarks in SDL_SensorType for
    /// details for each type of sensor.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="type">the type of sensor to query.</param>
    /// <param name="data">a pointer filled with the current sensor state.</param>
    /// <param name="numValues">the number of values to write to data.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool GetSensorData(SensorType type, float* data, int numValues) => Sdl.GetGamepadSensorData(this, type, data, numValues);

    /// <summary>Get the current state of a gamepad sensor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadSensorData</c>.</para>
    /// <para>
    /// The number of values and interpretation of the data is sensor dependent. See the remarks in SDL_SensorType for
    /// details for each type of sensor.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="type">the type of sensor to query.</param>
    /// <param name="data">a pointer filled with the current sensor state.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool GetSensorData(SensorType type, Span<float> data) => Sdl.GetGamepadSensorData(this, type, data);

    /// <summary>Start a rumble effect on a gamepad.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_RumbleGamepad</c>.</para>
    /// <para>
    /// Each call to this function cancels any previous rumble effect, and calling it with 0 intensity stops any
    /// rumbling.
    /// </para>
    /// <para>
    /// This function requires you to process SDL events or call SDL_UpdateJoysticks() to update rumble state.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="lowFrequencyRumble">
    /// the intensity of the low frequency (left) rumble motor, from 0 to 0xFFFF.
    /// </param>
    /// <param name="highFrequencyRumble">
    /// the intensity of the high frequency (right) rumble motor, from 0 to 0xFFFF.
    /// </param>
    /// <param name="durationMs">the duration of the rumble effect, in milliseconds.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool Rumble(ushort lowFrequencyRumble, ushort highFrequencyRumble, uint durationMs) => Sdl.RumbleGamepad(this, lowFrequencyRumble, highFrequencyRumble, durationMs);

    /// <summary>Start a rumble effect in the gamepad's triggers.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_RumbleGamepadTriggers</c>.</para>
    /// <para>
    /// Each call to this function cancels any previous trigger rumble effect, and calling it with 0 intensity stops any
    /// rumbling.
    /// </para>
    /// <para>
    /// Note that this is rumbling of the _triggers_ and not the gamepad as a whole. This is currently only supported on
    /// Xbox One gamepads. If you want the (more common) whole-gamepad rumble, use SDL_RumbleGamepad() instead.
    /// </para>
    /// <para>
    /// This function requires you to process SDL events or call SDL_UpdateJoysticks() to update rumble state.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_RumbleGamepad</c>.</para>
    /// </remarks>
    /// <param name="leftRumble">the intensity of the left trigger rumble motor, from 0 to 0xFFFF.</param>
    /// <param name="rightRumble">the intensity of the right trigger rumble motor, from 0 to 0xFFFF.</param>
    /// <param name="durationMs">the duration of the rumble effect, in milliseconds.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool RumbleTriggers(ushort leftRumble, ushort rightRumble, uint durationMs) => Sdl.RumbleGamepadTriggers(this, leftRumble, rightRumble, durationMs);

    /// <summary>Update a gamepad's LED color.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetGamepadLED</c>.</para>
    /// <para>An example of a joystick LED is the light on the back of a PlayStation 4's DualShock 4 controller.</para>
    /// <para>
    /// For gamepads with a single color LED, the maximum of the RGB values will be used as the LED brightness.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="red">the intensity of the red LED.</param>
    /// <param name="green">the intensity of the green LED.</param>
    /// <param name="blue">the intensity of the blue LED.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool SetLED(byte red, byte green, byte blue) => Sdl.SetGamepadLED(this, red, green, blue);

    /// <summary>Send a gamepad specific effect packet.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SendGamepadEffect</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="data">the data to send to the gamepad.</param>
    /// <param name="size">the size of the data to send to the gamepad.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool SendEffect(void* data, int size) => Sdl.SendGamepadEffect(this, data, size);

    /// <summary>Close a gamepad previously opened with SDL_OpenGamepad().</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CloseGamepad</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_OpenGamepad</c>.</para>
    /// </remarks>
    public void Close() => Sdl.CloseGamepad(this);

    /// <summary>Return the sfSymbolsName for a given button on a gamepad on Apple platforms.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadAppleSFSymbolsNameForButton</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetGamepadAppleSFSymbolsNameForAxis</c>.</para>
    /// </remarks>
    /// <param name="button">a button on the gamepad.</param>
    /// <returns>the sfSymbolsName or NULL if the name can't be found.</returns>
    public byte* GetAppleSFSymbolsNameForButton(GamepadButton button) => Sdl.GetGamepadAppleSFSymbolsNameForButton(this, button);

    /// <summary>Return the sfSymbolsName for a given axis on a gamepad on Apple platforms.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadAppleSFSymbolsNameForAxis</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetGamepadAppleSFSymbolsNameForButton</c>.</para>
    /// </remarks>
    /// <param name="axis">an axis on the gamepad.</param>
    /// <returns>the sfSymbolsName or NULL if the name can't be found.</returns>
    public byte* GetAppleSFSymbolsNameForAxis(GamepadAxis axis) => Sdl.GetGamepadAppleSFSymbolsNameForAxis(this, axis);
}
